import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`staff-scheduling`,heroTitle:`Build your staff schedule in minutes`,heroSubtitle:`Perplexity Computer analyzes your availability and sales data, builds optimized schedules, and flags coverage gaps — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your data`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls`,inputFilePrefill:`Review the uploaded file containing staff availability and sales history. 1) Parse all employee names, roles, availability windows, and any time-off requests. 2) Analyze the sales history to identify peak hours, slow periods, and day-of-week demand patterns. 3) Build an optimized weekly staff schedule that matches coverage to projected demand — ensuring peak times have adequate staffing and slow periods aren't overstaffed. 4) Flag any coverage gaps where demand exceeds available staff. 5) Identify no-show and flake patterns — which employees have reliability issues and which shifts are most affected. 6) Recommend specific staffing changes: shifts to add, roles to cross-train, and employees to prioritize for high-demand windows. 7) Calculate estimated labor cost per shift and highlight opportunities to reduce overtime. Deliver everything as a clear, printable schedule with a summary of gaps, risks, and recommended actions.`,heroOverlaySteps:[`Parsing staff availability, roles, and time-off requests`,`Analyzing sales history to map peak hours and demand patterns`,`Building optimized schedules and flagging coverage gaps`,`Schedule, gap report, and staffing recommendations — ready to review`],generatingSteps:[`Reading the uploaded file to extract availability, roles, and sales data`,`Designing an agent to match staffing levels to peak-hour demand patterns`,`Configuring coverage gap detection and no-show pattern analysis`,`Setting up schedule optimization with labor cost and overtime tracking`],featureSectionTitle:`From spreadsheet to optimized schedule`,featureCardTitles:[`Connects to your restaurant stack`,`Outputs you can post`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Slack, Notion — Computer pipes your optimized schedules and staffing alerts straight into the tools your team already uses.`,`Printable weekly schedules. Coverage gap reports. Peak-hour staffing maps. No-show pattern analysis. Labor cost breakdowns with overtime flags.`],capabilitySectionTitle:`Your scheduling manager, on autopilot`,capabilitySectionSubtitle:`Upload your data, step away, come back to a fully optimized schedule.`,capabilityCards:[{title:`Schedule Optimization`,description:`Computer can build weekly schedules that match staff to projected demand — maximizing coverage during rushes and trimming slow periods.`},{title:`Coverage Gap Detection`,description:`Computer can flag every shift where demand outpaces available staff — and recommend specific employees or roles to fill the gap.`},{title:`No-Show Analysis`,description:`Computer can identify which employees flake most, which shifts get hit hardest, and suggest backup coverage strategies to keep you protected.`},{title:`Connect Your Tools`,description:`Computer can push schedules to Google Sheets, send shift alerts via Slack, and sync availability updates from Google Drive — all in one workflow.`},{title:`Learns Your Patterns`,description:`Computer can remember your sales trends, staff preferences, and seasonal shifts across sessions — so every schedule gets smarter over time.`},{title:`Monitor & Alert`,description:`Computer can track call-outs and last-minute changes — and alert you when coverage drops below safe levels for an upcoming shift.`}]});export{t as default};
